mapper.select:
SELECT DISTINCT UO.PARTY_ID AS UO_ID , UOC.PARENT_ROLE_CODE AS UO_MAIN_CODE , UO.EXTERNAL_ID AS UO_OTHER_CODE , UO.PARTY_NAME AS UO_NAME , UO.PARTY_NAME_LANG AS UO_NAME_LANG FROM PARTY_PARENT_ROLE UOC INNER JOIN PARTY UO ON UO.PARTY_ID = UOC.PARTY_ID
INNER JOIN PARTY_ROLE PR ON PR.PARTY_ID = UO.PARTY_ID
LEFT JOIN PARTY_RELATIONSHIP UORES ON UORES.PARTY_ID_FROM = UO.PARTY_ID AND UORES.PARTY_RELATIONSHIP_TYPE_ID = 'ORG_RESPONSIBLE'
AND EXTRACT(YEAR FROM UORES.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM UORES.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (UORES.THRU_DATE IS NULL OR EXTRACT(YEAR FROM UORES.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND UORES.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (UORES.THRU_DATE IS NULL OR UORES.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
LEFT JOIN PARTY RES ON RES.PARTY_ID = UORES.PARTY_ID_TO LEFT OUTER JOIN PARTY_RELATIONSHIP ORGRD ON ORGRD.PARTY_RELATIONSHIP_TYPE_ID IN ('ORG_RESPONSIBLE', 'ORG_DELEGATE') AND ORGRD.ROLE_TYPE_ID_FROM = PR.ROLE_TYPE_ID AND ORGRD.PARTY_ID_FROM = PR.PARTY_ID AND ORGRD.PARTY_ID_TO = UO.PARTY_ID
AND EXTRACT(YEAR FROM ORGRD.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM ORGRD.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (ORGRD.THRU_DATE IS NULL OR EXTRACT(YEAR FROM ORGRD.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND ORGRD.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (ORGRD.THRU_DATE IS NULL OR ORGRD.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
LEFT OUTER JOIN PARTY_RELATIONSHIP SUPORG ON SUPORG.PARTY_RELATIONSHIP_TYPE_ID = 'GROUP_ROLLUP' AND SUPORG.ROLE_TYPE_ID_TO = PR.ROLE_TYPE_ID AND SUPORG.PARTY_ID_TO = PR.PARTY_ID
AND EXTRACT(YEAR FROM SUPORG.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM SUPORG.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (SUPORG.THRU_DATE IS NULL OR EXTRACT(YEAR FROM SUPORG.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND SUPORG.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (SUPORG.THRU_DATE IS NULL OR SUPORG.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
LEFT OUTER JOIN PARTY_RELATIONSHIP SUPRD ON SUPRD.PARTY_RELATIONSHIP_TYPE_ID IN ('ORG_RESPONSIBLE', 'ORG_DELEGATE') AND SUPRD.ROLE_TYPE_ID_FROM = SUPORG.ROLE_TYPE_ID_FROM AND SUPRD.PARTY_ID_FROM = SUPORG.PARTY_ID_FROM AND SUPRD.PARTY_ID_TO = UO.PARTY_ID
AND EXTRACT(YEAR FROM SUPRD.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM SUPRD.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (SUPRD.THRU_DATE IS NULL OR EXTRACT(YEAR FROM SUPRD.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND SUPRD.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (SUPRD.THRU_DATE IS NULL OR SUPRD.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
LEFT OUTER JOIN PARTY_RELATIONSHIP TOPSUP ON TOPSUP.PARTY_RELATIONSHIP_TYPE_ID = 'GROUP_ROLLUP' AND TOPSUP.ROLE_TYPE_ID_TO = SUPORG.ROLE_TYPE_ID_FROM AND TOPSUP.PARTY_ID_TO = SUPORG.PARTY_ID_FROM
AND EXTRACT(YEAR FROM TOPSUP.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM TOPSUP.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (TOPSUP.THRU_DATE IS NULL OR EXTRACT(YEAR FROM TOPSUP.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND TOPSUP.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (TOPSUP.THRU_DATE IS NULL OR TOPSUP.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
LEFT OUTER JOIN PARTY_RELATIONSHIP TOPRD ON TOPRD.PARTY_RELATIONSHIP_TYPE_ID IN ('ORG_RESPONSIBLE', 'ORG_DELEGATE') AND TOPRD.ROLE_TYPE_ID_FROM = TOPSUP.ROLE_TYPE_ID_FROM AND TOPRD.PARTY_ID_FROM = TOPSUP.PARTY_ID_FROM AND TOPRD.PARTY_ID_TO = UO.PARTY_ID
AND EXTRACT(YEAR FROM TOPRD.FROM_DATE) >= #{startYear,jdbcType=NUMERIC}
AND EXTRACT(YEAR FROM TOPRD.FROM_DATE) >= #{endYear,jdbcType=NUMERIC}
AND (TOPRD.THRU_DATE IS NULL OR EXTRACT(YEAR FROM TOPRD.THRU_DATE) <= #{endYear,jdbcType=NUMERIC})
AND TOPRD.FROM_DATE <= #{refDate,jdbcType=TIMESTAMP} AND (TOPRD.THRU_DATE IS NULL OR TOPRD.THRU_DATE >= #{refDate,jdbcType=TIMESTAMP})
WHERE UOC.ORGANIZATION_ID = #{organizationId, mode=IN, jdbcType=VARCHAR} AND UOC.ROLE_TYPE_ID = 'ORGANIZATION_UNIT'
AND PR.ROLE_TYPE_ID = #{roleTypeId, mode=IN, jdbcType=VARCHAR}
AND (
(ORGRD.PARTY_ID_TO IS NOT NULL AND (ORGRD.CTX_ENABLED IS NULL OR ORGRD.CTX_ENABLED LIKE CONCAT('%', CONCAT(WET.PARENT_TYPE_ID,'%'))))
OR
(SUPRD.PARTY_ID_TO IS NOT NULL AND (SUPRD.CTX_ENABLED IS NULL OR SUPRD.CTX_ENABLED LIKE CONCAT('%', CONCAT(WET.PARENT_TYPE_ID,'%'))))
OR
(TOPRD.PARTY_ID_TO IS NOT NULL AND (TOPRD.CTX_ENABLED IS NULL OR TOPRD.CTX_ENABLED LIKE CONCAT('%', CONCAT(WET.PARENT_TYPE_ID,'%'))))
)
ORDER BY UO.PARTY_NAME_LANGUO.PARTY_NAME
ORDER BY UOC.PARENT_ROLE_CODE
ORDER BY UO.EXTERNAL_ID
